/* The shell: the sidebars, the menus and the few widgets that have state.
 *
 * Generated by brandkit. Delete what you are not using - most applications
 * want the sidebar and none of the rest, and nothing here depends on anything
 * else here.
 *
 * Everything that *can* be done in CSS is: the theme, the responsive layout,
 * every hover and focus state. What is left is the handful of things a
 * browser genuinely has no element for - a panel that is a column at one width
 * and a drawer at another, a menu that closes when you click elsewhere - and
 * each of them sets an attribute or a class that the stylesheet already knows
 * about, rather than writing a style.
 */
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];

const app = $("#app");

/* The chevron points the way the panel will move, so the button says what it
 * is about to do rather than what it currently is. It is the one icon in the
 * set that is used rotated; a second glyph facing the other way would be a
 * second thing to keep in step. */
function point(button, degrees) {
  const glyph = button && $("svg", button);
  if (glyph) glyph.style.rotate = `${degrees}deg`;
}

/* ------------------------------------------------------- the left sidebar */

function setLeft(collapsed) {
  app.classList.toggle("collapsed", collapsed);
  const button = $("#collapse-btn");
  if (!button) return;
  button.setAttribute("aria-label",
                      collapsed ? "Expand sidebar" : "Collapse sidebar");
  point(button, collapsed ? 90 : -90);
}

$("#collapse-btn")?.addEventListener("click", () => {
  setLeft(!app.classList.contains("collapsed"));
});

/* Below the drawer breakpoint the sidebar slides in over the page instead of
 * taking a column, because three columns do not fit on a phone and two barely
 * do. The menu button in the header is the only way in at that width. */
$("#menu-toggle")?.addEventListener("click", (event) => {
  const open = app.classList.toggle("nav-open");
  event.currentTarget.setAttribute("aria-expanded", String(open));
});

/* Following a link in a drawer should close the drawer. On a wide screen the
 * class is not set and this does nothing. */
$$(".side-link").forEach((link) => link.addEventListener("click", () => {
  app.classList.remove("nav-open");
}));

/* ------------------------------------------------------ the right sidebar */

/* One state machine for two behaviours, because they are one panel: wide, it
 * collapses to a rail; narrow, it slides in as a drawer. Keeping them apart
 * is how a panel ends up open in one sense and closed in the other after a
 * window is resized across the line. */
const narrow = matchMedia("(max-width: 1100px)");

function rightIsOpen() {
  return narrow.matches
    ? app.classList.contains("right-open")
    : !app.classList.contains("right-collapsed");
}

function setRight(open) {
  if (narrow.matches) {
    app.classList.toggle("right-open", open);
  } else {
    app.classList.toggle("right-collapsed", !open);
  }
  const button = $("#right-collapse-btn");
  if (button) {
    button.setAttribute("aria-label",
                        open ? "Collapse details" : "Expand details");
    point(button, open ? 90 : -90);
  }
  $("#details-btn")?.setAttribute("aria-pressed", String(open));
}

if ($("#sidebar-right")) {
  $("#right-collapse-btn")?.addEventListener(
    "click", () => setRight(!rightIsOpen()));
  // ...and from the page as well, because at a rail or in a drawer the control
  // inside it is the one thing you cannot reach.
  $("#details-btn")?.addEventListener("click", () => setRight(!rightIsOpen()));
  // Crossing the breakpoint changes which class means "open", so both are
  // cleared and the panel is set again from scratch.
  narrow.addEventListener("change", () => {
    app.classList.remove("right-open", "right-collapsed");
    setRight(!narrow.matches);
  });
  setRight(!narrow.matches);
}

/* ------------------------------------------------------------- the menus */

/* A popover with a trigger. The element has no browser equivalent that also
 * carries a heading and a divider, so this is the one place a menu is built
 * by hand - and it is still only the open state, the outside click and the
 * escape key. */
function popover(button, menu) {
  if (!button || !menu) return;
  button.addEventListener("click", (event) => {
    event.stopPropagation();
    const opening = menu.hidden;
    $$(".menu").forEach((other) => { other.hidden = true; });
    menu.hidden = !opening;
    button.setAttribute("aria-expanded", String(opening));
  });
}

popover($("#user-btn"), $("#user-menu"));

function closeMenus() {
  $$(".menu").forEach((menu) => { menu.hidden = true; });
  $$("[aria-haspopup]").forEach((button) => {
    button.setAttribute("aria-expanded", "false");
  });
}

addEventListener("click", closeMenus);
addEventListener("keydown", (event) => {
  if (event.key === "Escape") closeMenus();
  // "/" focuses the search, which is what every application with a search box
  // does and what people try first.
  const typing = /INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName);
  if (event.key === "/" && !typing && $("#search")) {
    event.preventDefault();
    $("#search").focus();
  }
});

/* --------------------------------------------- the widgets that hold state */

/* Each of these sets the ARIA attribute that the stylesheet selects on, so the
 * thing that is true for a screen reader and the thing that is true visually
 * are the same thing rather than two things kept in step. */
$$(".tabs").forEach((group) => group.addEventListener("click", (event) => {
  const tab = event.target.closest(".tab");
  if (!tab) return;
  $$(".tab", group).forEach((other) => {
    other.setAttribute("aria-selected", String(other === tab));
  });
}));

$$(".seg, .btn-group").forEach((group) => group.addEventListener("click",
                                                                 (event) => {
  const button = event.target.closest("button");
  if (!button) return;
  $$("button", group).forEach((other) => {
    other.setAttribute("aria-pressed", String(other === button));
  });
}));

$$(".chip").forEach((chip) => chip.addEventListener("click", () => {
  chip.setAttribute("aria-pressed",
                    String(chip.getAttribute("aria-pressed") !== "true"));
}));

/* A native <dialog> brings its own focus trap, its own escape key and its own
 * backdrop. The only thing it does not do is close when the backdrop is
 * clicked, because the backdrop is part of the dialog as far as the event is
 * concerned - so the test is whether the click landed on the element itself
 * rather than on anything inside it. */
$$("dialog").forEach((box) => box.addEventListener("click", (event) => {
  if (event.target === box) box.close();
}));

$$(".alert .close").forEach((button) => button.addEventListener("click", () => {
  button.closest(".alert").remove();
}));

/* A message that announces itself. The region is aria-live="polite", so it is
 * read after whatever the reader is in the middle of rather than over it. */
function toast(message, kind) {
  const tray = $("#toasts");
  if (!tray) return;
  const glyph = { ok: "i-ok", warn: "i-alert", bad: "i-error" }[kind]
              || "i-info";
  const note = document.createElement("div");
  note.className = "toast";
  note.innerHTML =
    `<svg class="icon"><use href="#${glyph}"></use></svg>`
    + `<div class="grow"></div>`
    + `<button class="btn ghost sm" type="button">Dismiss</button>`;
  // textContent, not innerHTML: a message is text, and somewhere behind every
  // toast is a string somebody else wrote.
  $(".grow", note).textContent = message;
  $("button", note).addEventListener("click", () => note.remove());
  tray.append(note);
  setTimeout(() => note.remove(), 4500);
}
